$summary+=array('recipients'=>0,'delivered'=>0,'failed'=>0,'waiting'=>0,'suppressed'=>0,'unsubscribed'=>0,'opened'=>0,'open_hits'=>0,'clicked'=>0,'click_hits'=>0,'open_rate'=>0,'click_rate'=>0,'click_to_open'=>0,'trackable'=>false);
$timeline=!empty($report_timeline)?$report_timeline:array();$links=!empty($report_links)?$report_links:array();
$delivery=$report_delivery??array();$tracksOpens=$channel==='email';
$pct=function($value){return number_format((float)$value,1).'%';};
?>
<?php if(!$report_campaign): ?>
<section class="comm-card"><div class="comm-head"><div><h2>Campaign results</h2><p class="muted">Choose a campaign to see who received it, who read it and which links were clicked.</p></div><a class="btn secondary" href="<?= $h($workspace_url('campaigns')); ?>">All campaigns</a></div>
<div class="comm-scroll"><table class="comm-table"><thead><tr><th>Campaign</th><th>Status</th><th>Recipients</th><th>Delivered</th><th>Failed</th><th>Created</th><th>Results</th></tr></thead><tbody><?php foreach($report_list as $c): ?><tr><td><b><?= $h($c->name); ?></b><br><span class="muted"><?= $h($c->subject?:'SMS campaign'); ?></span></td><td><span class="comm-badge <?= $c->status==='sent'?'ok':'off'; ?>"><?= $h($c->status); ?></span></td><td><?= number_format((int)$c->audience_count); ?></td><td><?= number_format((int)$c->sent_count); ?></td><td><?= number_format((int)$c->failed_count); ?></td><td><?= $h($c->created_at); ?></td><td><a class="btn secondary" href="<?= $h($workspace_url('report',array('campaign'=>(int)$c->id))); ?>">View results</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php if(!$report_list): ?><p class="empty">Results appear here as soon as one of your <?= $channel==='sms'?'SMS':'email'; ?> campaigns has been sent.</p><?php endif; ?>
<?php if(count($report_list)>=25): ?><p class="muted">Showing your 25 most recent campaigns. Start from the campaign list to look up an older one.</p><?php endif; ?></section>
<?php endif; ?>

<?php if($report_campaign): ?><?php $total=(int)$recipients['total']; ?>
<section class="comm-card"><div class="comm-head"><div><span class="comm-eyebrow">Campaign results</span><h2><?= $h($report_campaign['name']); ?></h2><p class="muted"><?= $h($report_campaign['subject']?:'SMS campaign'); ?> · created <?= $h($report_campaign['created_at']); ?></p></div><div class="row"><span class="comm-badge <?= $report_campaign['status']==='sent'?'ok':'off'; ?>"><?= $h($report_campaign['status']); ?></span><a class="btn secondary" href="<?= $h($workspace_url('report')); ?>">Another campaign</a></div></div>
<div class="comm-grid"><article class="comm-card"><span class="muted">Recipients</span><div class="metric"><?= number_format((int)$summary['recipients']); ?></div><span class="muted">In this campaign audience</span></article>
<article class="comm-card"><span class="muted"><?= $tracksOpens?'Delivered':'Accepted by the network'; ?></span><div class="metric"><?= number_format((int)$summary['delivered']); ?></div><span class="muted"><?= number_format((int)$summary['waiting']); ?> still waiting for their turn</span></article>
<?php if($tracksOpens): ?><article class="comm-card"><span class="muted">Opened</span><div class="metric"><?= number_format((int)$summary['opened']); ?></div><span class="muted"><?= $pct($summary['open_rate']); ?> of delivered · <?= number_format((int)$summary['open_hits']); ?> reads counted</span></article>
<article class="comm-card"><span class="muted">Clicked a link</span><div class="metric"><?= number_format((int)$summary['clicked']); ?></div><span class="muted"><?= $pct($summary['click_rate']); ?> of delivered · <?= $pct($summary['click_to_open']); ?> of readers</span></article><?php endif; ?>
<article class="comm-card"><span class="muted">Not delivered</span><div class="metric"><?= number_format((int)$summary['failed']); ?></div><span class="muted"><?= number_format((int)$summary['unsubscribed']); ?> chose to stop receiving these</span></article></div>
<?php if($tracksOpens): ?><p class="muted">An open is counted when the message is displayed with images allowed. Mail apps that block images or pre-check mail do not report every read, so opens are a dependable minimum rather than a head count.</p><?php endif; ?>
<?php if($delivery): ?><p class="muted">Provider confirmations: <?= number_format((int)$delivery['delivered']); ?> accepted, <?= number_format((int)$delivery['failed']); ?> refused, <?= number_format((int)$delivery['awaiting']); ?> awaiting confirmation. <?= $status_text($delivery['note']); ?></p><?php endif; ?></section>

<?php if($tracksOpens && $timeline): ?><?php $peak=1;foreach($timeline as $day)$peak=max($peak,(int)$day['opened'],(int)$day['clicked']);$scale=88/$peak; ?>
<section class="comm-card"><div class="comm-head"><div><h2>Reads and clicks by day</h2><p class="muted">The last 14 days, counted from when each message was opened.</p></div><div class="row"><span class="mini"><span style="display:inline-block;width:10px;height:10px;border-radius:3px;background:var(--ca);vertical-align:middle"></span> Opens</span><span class="mini"><span style="display:inline-block;width:10px;height:10px;border-radius:3px;background:var(--ci);vertical-align:middle"></span> Clicks</span></div></div>
<div style="display:flex;gap:8px;align-items:flex-end;overflow-x:auto;padding:8px 0 4px"><?php foreach($timeline as $day): ?><div style="flex:1 0 44px;text-align:center" title="<?= number_format((int)$day['opened']); ?> opens and <?= number_format((int)$day['clicked']); ?> clicks on <?= $h($day['day']); ?>"><div style="display:flex;gap:3px;align-items:flex-end;justify-content:center;height:92px"><span style="width:12px;border-radius:3px 3px 0 0;background:var(--ca);height:<?= (int)$day['opened']>0?max(4,(int)round($day['opened']*$scale)):2 ?>px;<?= (int)$day['opened']>0?'':'opacity:.25'; ?>"></span><span style="width:12px;border-radius:3px 3px 0 0;background:var(--ci);height:<?= (int)$day['clicked']>0?max(4,(int)round($day['clicked']*$scale)):2 ?>px;<?= (int)$day['clicked']>0?'':'opacity:.25'; ?>"></span></div><div class="mini muted"><?= $h($day['label']); ?></div></div><?php endforeach; ?></div></section><?php endif; ?>

<?php if($tracksOpens && $links): ?>
<section class="comm-card"><div class="comm-head"><div><h2>Links people opened</h2><p class="muted">Ranked by clicks. Only links inside the delivered message are counted.</p></div></div><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Link</th><th>Clicks</th><th>People</th></tr></thead><tbody><?php foreach($links as $link): ?><tr><td><?= $h($link['label']); ?></td><td><?= number_format((int)$link['clicks']); ?></td><td><?= number_format((int)$link['people']); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>

<?php $filters=$tracksOpens?array('all'=>'Everyone','opened'=>'Opened','clicked'=>'Clicked','failed'=>'Not delivered','waiting'=>'Still queued'):array('all'=>'Everyone','failed'=>'Not delivered','waiting'=>'Still queued'); ?>
<section class="comm-card" id="report-recipients"><div class="comm-head"><div><h2>Recipient activity</h2><p class="muted"><?= number_format($total); ?> <?= $total===1?'person matches':'people match'; ?> this filter.</p></div></div>
<div class="comm-toolbar"><?php foreach($filters as $key=>$label): ?><a class="btn <?= $recipients['filter']===$key?'':'secondary'; ?>" href="<?= $h($workspace_url('report',array('campaign'=>(int)$report_campaign['id'],'filter'=>$key))); ?>"><?= $h($label); ?></a><?php endforeach; ?></div>
<div class="comm-scroll"><table class="comm-table"><thead><tr><th>Recipient</th><th>Result</th><?php if($tracksOpens): ?><th>Opens</th><th>Clicks</th><?php endif; ?><th>Delivered</th></tr></thead><tbody><?php foreach($recipients['rows'] as $row): ?><tr><td><b><?= $h($row['display']); ?></b><?php if($row['display']!==$row['recipient']): ?><br><span class="muted"><?= $h($row['recipient']); ?></span><?php endif; ?></td><td><span class="comm-badge <?= $row['status']==='sent'?'ok':'off'; ?>"><?= $h($row['outcome']); ?></span><?php if(!empty($row['error'])): ?><br><span class="mini muted"><?= $status_text($row['error']); ?></span><?php endif; ?></td><?php if($tracksOpens): ?><td><?= number_format((int)$row['open_count']); ?></td><td><?= number_format((int)$row['click_count']); ?></td><?php endif; ?><td class="mini"><?= $h($row['sent_at']?:'—'); ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if(!$recipients['rows']): ?><p class="empty">Nobody in this campaign matches that filter yet.</p><?php endif; ?>
<?php if((int)$recipients['pages']>1): ?><div class="row"><?php for($page=1;$page<=(int)$recipients['pages'];$page++): ?><a class="btn <?= $page===(int)$recipients['page']?'':'secondary'; ?>" href="<?= $h($workspace_url('report',array('campaign'=>(int)$report_campaign['id'],'filter'=>$recipients['filter'],'report_page'=>$page))); ?>"><?= $page; ?></a><?php endfor; ?></div><?php endif; ?>
<p class="muted">Showing <?= number_format(count($recipients['rows'])); ?> of <?= number_format($total); ?>.<?= $tracksOpens?' A contact who opens the same message twice within the hour is counted once.':' Each recipient is listed once, from their latest send attempt.'; ?></p></section>
<?php endif; ?>
